536	+// The rule for a modal window no listener answered. Nothing to return shows it.
537	+std::optional<int> take_modal(wxDialog& dialog)
538	+{
539	+    if (!view_takes_messages())
540	+        return std::nullopt;
541	+    const DialogFacts facts = read_dialog(dialog);
542	+    if (facts.picker) {
543	+        show(dialog, "a picker");
544	+        return std::nullopt;
545	+    }
546	+    if (dynamic_cast<UnsavedChangesDialog*>(&dialog) != nullptr) {
547	+        // The class also serves "copy one nozzle's settings to the other",
548	+        // which is a question about a copy and stays. The two uses that ask
549	+        // what to do with unsaved edits are told by their titles, looked up
550	+        // as OrcaSlicer looks them up.
551	+        const wxString title        = dialog.GetTitle();
552	+        const bool     preset_switch = title == _L("Transfer or discard changes");
553	+        const bool     before_reload = title.EndsWith(": " + _L("unsaved changes"));
554	+        if ((preset_switch || before_reload) && g_save_version && g_save_version()) {
555	+            // A switch of preset goes on to drop the outgoing preset's edits
556	+            // itself; the other callers read the dialog's choice, so the
557	+            // edits are dropped here.
558	+            if (before_reload)
559	+                discard_preset_edits();
560	+            take(TakenMessage::From::UnsavedChanges, std::string(title.ToUTF8().data()), "A version was saved and the unsaved setting changes were dropped.");
561	+            return wxID_OK;
562	+        }
563	+        show(dialog, preset_switch || before_reload ? "unsaved changes, and no version could be saved" : "a question about copying settings");
564	+        return std::nullopt;
565	+    }
566	+    if (dynamic_cast<TipsDialog*>(&dialog) != nullptr && !facts.yes && !facts.no) {
567	+        take(TakenMessage::From::Tip, facts.title, facts.text);
568	+        return wxID_OK;
569	+    }
570	+    const bool message_box = dynamic_cast<MsgDialog*>(&dialog) != nullptr || dynamic_cast<wxMessageDialogBase*>(&dialog) != nullptr;
571	+    if (!message_box) {
572	+        show(dialog, "a window");
573	+        return std::nullopt;
574	+    }
575	+    const bool only_ok = facts.ok && !facts.yes && !facts.no && !facts.cancel &&
576	+                         (dynamic_cast<wxMessageDialogBase*>(&dialog) != nullptr || count_buttons(dialog) == 1);
577	+    if (!only_ok) {
578	+        show(dialog, "a question");
579	+        return std::nullopt;
580	+    }
581	+    if (current_cause().kind == Cause::Kind::None && another_window_is_open(dialog.GetParent(), &dialog)) {
582	+        show(dialog, "a message, with another window open");
583	+        return std::nullopt;
584	+    }
585	+    take(TakenMessage::From::Box, facts.title, facts.text);
586	+    return wxID_OK;
587	+}
