+// ---------------------------------------------------------------------------
+// PROTOTYPE (2026-11-18, not for landing): what OrcaSlicer says while the
+// JusPrin view is on screen. See DialogListeners.hpp.
+// ---------------------------------------------------------------------------
+
+namespace {
+
+bool                     g_view_takes_messages = false;
+std::function<bool()>    g_save_version;
+std::function<void(const TakenMessage&)> g_taken_listener;
+ScopedCause*             g_cause_scope = nullptr;
+Cause                    g_noted_cause;
+unsigned                 g_noted_token = 0;
+std::vector<TakenMessage>& taken_store()
+{
+    static auto* const list = new std::vector<TakenMessage>;
+    return *list;
+}
+std::vector<ShownWindow>& shown_store()
+{
+    static auto* const list = new std::vector<ShownWindow>;
+    return *list;
+}
+
+// JUSPRIN_ORCA_MESSAGES=off leaves every window to OrcaSlicer, as before the
+// prototype: the "before" half of a before-and-after run.
+bool switched_off()
+{
+    static const bool off = [] {
+        const char* value = std::getenv("JUSPRIN_ORCA_MESSAGES");
+        return value != nullptr && std::string(value) == "off";
+    }();
+    return off;
+}
+
+void take(TakenMessage::From from, std::string title, std::string text)
+{
+    TakenMessage message{from, current_cause(), std::move(title), std::move(text)};
+    BOOST_LOG_TRIVIAL(info) << "JusPrin took OrcaSlicer's message (" << from_name(from) << ", cause " << cause_name(message.cause.kind)
+                            << ", printer \"" << message.cause.printer << "\"): " << message.text;
+    taken_store().push_back(std::move(message));
+    if (g_taken_listener)
+        g_taken_listener(taken_store().back());
+}
+
+int count_buttons(wxWindow& window)
+{
+    int count = 0;
+    for (wxWindow* child : window.GetChildren()) {
+        if (!child->IsShown())
+            continue;
+        if (dynamic_cast<::Button*>(child) != nullptr || dynamic_cast<wxButton*>(child) != nullptr)
+            ++count;
+        count += count_buttons(*child);
+    }
+    return count;
+}
+
+// Whether the person has another window open over the main one: OrcaSlicer's
+// settings window, the send dialog, the monitor, Preferences. A box that
+// opens then belongs with that window, where they are looking.
+bool another_window_is_open(const wxWindow* parent, const wxWindow* box)
+{
+    const wxWindow* frame = wxGetApp().mainframe;
+    if (parent != nullptr)
+        if (const wxWindow* top = wxGetTopLevelParent(const_cast<wxWindow*>(parent)); top != nullptr && top != frame && top != box)
+            return true;
+    for (const wxWindow* window : wxTopLevelWindows) {
+        if (window == frame || window == box || !window->IsShown())
+            continue;
+        if (dynamic_cast<const wxDialog*>(window) != nullptr || dynamic_cast<const wxFrame*>(window) != nullptr) {
+            BOOST_LOG_TRIVIAL(info) << "JusPrin: another window is open: \"" << window->GetLabel().ToUTF8().data() << "\" (" << typeid(*window).name() << ")";
+            return true;
+        }
+    }
+    return false;
+}
+
+void show(wxDialog& dialog, const char* why)
+{
+    const auto& type = typeid(dialog);
+    shown_store().push_back({type.name(), std::string(dialog.GetTitle().ToUTF8().data()), why});
+    BOOST_LOG_TRIVIAL(info) << "JusPrin let the window \"" << dialog.GetTitle().ToUTF8().data() << "\" (" << type.name() << ") through: " << why;
+}
+
+// OrcaSlicer's own Discard, for every preset with unsaved edits.
+void discard_preset_edits()
+{
+    for (Tab* tab : wxGetApp().tabs_list)
+        if (tab->get_presets() != nullptr && tab->get_presets()->current_is_dirty())
+            tab->get_presets()->discard_current_changes();
+    wxGetApp().load_current_presets(false);
+}
+
+} // namespace
+
+const char* cause_name(Cause::Kind kind)
+{
+    switch (kind) {
+    case Cause::Kind::None: return "none";
+    case Cause::Kind::PrinterConnection: return "printer_connection";
+    case Cause::Kind::PrinterMessage: return "printer_message";
+    case Cause::Kind::PluginMessage: return "plugin_message";
+    case Cause::Kind::Slice: return "slice";
+    case Cause::Kind::HostUpload: return "host_upload";
+    }
+    return "";
+}
+
+const char* from_name(TakenMessage::From from)
+{
+    switch (from) {
+    case TakenMessage::From::Box: return "box";
+    case TakenMessage::From::ErrorBox: return "error_box";
+    case TakenMessage::From::AppDialog: return "app_dialog";
+    case TakenMessage::From::PrinterNotification: return "printer_notification";
+    case TakenMessage::From::UnsavedChanges: return "unsaved_changes";
+    case TakenMessage::From::Tip: return "tip";
+    case TakenMessage::From::PageSwitch: return "page_switch";
+    }
+    return "";
+}
+
+ScopedCause::ScopedCause(Cause::Kind kind, std::string printer, std::string detail)
+    : m_cause{kind, std::move(printer), std::move(detail)}, m_outer(g_cause_scope)
+{
+    g_cause_scope = this;
+}
+
+ScopedCause::~ScopedCause() { g_cause_scope = m_outer; }
+
+void note_cause(Cause cause)
+{
+    g_noted_cause = std::move(cause);
+    const unsigned token = ++g_noted_token;
+    // Queued behind the event now being handled, so it runs once that has ended.
+    if (wxTheApp != nullptr)
+        wxTheApp->CallAfter([token] {
+            if (g_noted_token == token)
+                g_noted_cause = {};
+        });
+}
+
+Cause current_cause() { return g_cause_scope != nullptr ? g_cause_scope->m_cause : g_noted_cause; }
+
+void set_view_takes_messages(bool on, std::function<bool()> save_version)
+{
+    ensure_hook();
+    g_view_takes_messages = on;
+    g_save_version        = std::move(save_version);
+}
+
+bool view_takes_messages() { return g_view_takes_messages && !switched_off(); }
+
+void set_taken_message_listener(std::function<void(const TakenMessage&)> listener) { g_taken_listener = std::move(listener); }
+
+const std::vector<TakenMessage>& taken_messages() { return taken_store(); }
+const std::vector<ShownWindow>&  shown_windows() { return shown_store(); }
+
+bool take_error(const std::string& text, wxWindow* parent)
+{
+    // A tool call or a file open has its own listener, which answers the box
+    // when it opens.
+    if (!view_takes_messages() || !wxIsMainThread() || g_innermost != nullptr)
+        return false;
+    if (current_cause().kind == Cause::Kind::None && another_window_is_open(parent, nullptr))
+        return false;
+    take(TakenMessage::From::ErrorBox, {}, text);
+    return true;
+}
+
+bool take_app_dialog(const std::string& text)
+{
+    if (!view_takes_messages() || !wxIsMainThread())
+        return false;
+    if (current_cause().kind == Cause::Kind::None && another_window_is_open(nullptr, nullptr))
+        return false;
+    take(TakenMessage::From::AppDialog, {}, text);
+    return true;
+}
+
+bool take_printer_notification(const std::string& device_id, const std::string& text, const std::string& title)
+{
+    if (!view_takes_messages() || !wxIsMainThread())
+        return false;
+    const ScopedCause cause(Cause::Kind::PrinterMessage, device_id, {});
+    take(TakenMessage::From::PrinterNotification, title, text);
+    return true;
+}
+
+void note_refused_page(const std::string& page) { take(TakenMessage::From::PageSwitch, {}, page); }
+
+// The rule for a modal window no listener answered. Nothing to return shows it.
+std::optional<int> take_modal(wxDialog& dialog)
+{
+    if (!view_takes_messages())
+        return std::nullopt;
+    const DialogFacts facts = read_dialog(dialog);
+    if (facts.picker) {
+        show(dialog, "a picker");
+        return std::nullopt;
+    }
+    if (dynamic_cast<UnsavedChangesDialog*>(&dialog) != nullptr) {
+        // The class also serves "copy one nozzle's settings to the other",
+        // which is a question about a copy and stays. The two uses that ask
+        // what to do with unsaved edits are told by their titles, looked up
+        // as OrcaSlicer looks them up.
+        const wxString title        = dialog.GetTitle();
+        const bool     preset_switch = title == _L("Transfer or discard changes");
+        const bool     before_reload = title.EndsWith(": " + _L("unsaved changes"));
+        if ((preset_switch || before_reload) && g_save_version && g_save_version()) {
+            // A switch of preset goes on to drop the outgoing preset's edits
+            // itself; the other callers read the dialog's choice, so the
+            // edits are dropped here.
+            if (before_reload)
+                discard_preset_edits();
+            take(TakenMessage::From::UnsavedChanges, std::string(title.ToUTF8().data()), "A version was saved and the unsaved setting changes were dropped.");
+            return wxID_OK;
+        }
+        show(dialog, preset_switch || before_reload ? "unsaved changes, and no version could be saved" : "a question about copying settings");
+        return std::nullopt;
+    }
+    if (dynamic_cast<TipsDialog*>(&dialog) != nullptr && !facts.yes && !facts.no) {
+        take(TakenMessage::From::Tip, facts.title, facts.text);
+        return wxID_OK;
+    }
+    const bool message_box = dynamic_cast<MsgDialog*>(&dialog) != nullptr || dynamic_cast<wxMessageDialogBase*>(&dialog) != nullptr;
+    if (!message_box) {
+        show(dialog, "a window");
+        return std::nullopt;
+    }
+    const bool only_ok = facts.ok && !facts.yes && !facts.no && !facts.cancel &&
+                         (dynamic_cast<wxMessageDialogBase*>(&dialog) != nullptr || count_buttons(dialog) == 1);
+    if (!only_ok) {
+        show(dialog, "a question");
+        return std::nullopt;
+    }
+    if (current_cause().kind == Cause::Kind::None && another_window_is_open(dialog.GetParent(), &dialog)) {
+        show(dialog, "a message, with another window open");
+        return std::nullopt;
+    }
+    take(TakenMessage::From::Box, facts.title, facts.text);
+    return wxID_OK;
+}
+
 } // namespace Slic3r::GUI::JusPrin::Workspace
