+// ---------------------------------------------------------------------------
+// PROTOTYPE (2026-11-18, not for landing): what OrcaSlicer says while the
+// JusPrin view is on screen.
+//
+// A message is taken at the last point where its reason is still known. For
+// a box OrcaSlicer opens at once that is the moment it opens: the code that
+// asked for it is still running, so the cause it noted is still set. For a
+// message OrcaSlicer puts off until later (show_error, GUI_App::show_dialog,
+// GUI_App::push_notification) it is the function that puts it off, which has
+// one line calling in here.
+// ---------------------------------------------------------------------------
+
+// What the app was handling when OrcaSlicer spoke. Noted by the code at the
+// source, which is the only place that knows it.
+struct Cause
+{
+    enum class Kind { None, PrinterConnection, PrinterMessage, PluginMessage, Slice, HostUpload };
+    Kind        kind{Kind::None};
+    std::string printer; // a Bambu device id, or a print host's address
+    std::string detail;  // the plug-in's code, the file being uploaded
+};
+const char* cause_name(Cause::Kind kind);
+
+// The cause for the calls made while this lives.
+class ScopedCause
+{
+public:
+    ScopedCause(Cause::Kind kind, std::string printer, std::string detail);
+    ~ScopedCause();
+    ScopedCause(const ScopedCause&)            = delete;
+    ScopedCause& operator=(const ScopedCause&) = delete;
+
+private:
+    Cause        m_cause;
+    ScopedCause* m_outer{nullptr};
+    friend Cause current_cause();
+};
+// The cause until the event now being handled has ended: for a listener that
+// returns before OrcaSlicer's own handler of the same event runs.
+void  note_cause(Cause cause);
+Cause current_cause();
+
+// One thing OrcaSlicer wanted to tell the person, taken before its window
+// opened, with the reason it was said.
+struct TakenMessage
+{
+    enum class From { Box, ErrorBox, AppDialog, PrinterNotification, UnsavedChanges, Tip, PageSwitch };
+    From        from{From::Box};
+    Cause       cause;
+    std::string title;
+    std::string text;
+};
+const char* from_name(TakenMessage::From from);
+
+// A window that was let through to the person, and why.
+struct ShownWindow
+{
+    std::string window_class;
+    std::string title;
+    std::string why;
+};
+
+// On while the JusPrin view is installed. `save_version` saves the project to
+// its version history and says whether it did.
+void set_view_takes_messages(bool on, std::function<bool()> save_version = {});
+bool view_takes_messages();
+
+// The hand-over points. True when the message was taken, so OrcaSlicer's
+// window must not open.
+bool take_error(const std::string& text, wxWindow* parent);
+bool take_app_dialog(const std::string& text);
+bool take_printer_notification(const std::string& device_id, const std::string& text, const std::string& title);
+// A switch of the main window to `page` was refused.
+void note_refused_page(const std::string& page);
+
+// Told of each message as it is taken: the view shows it in the place its
+// cause names.
+void set_taken_message_listener(std::function<void(const TakenMessage&)> listener);
+
+const std::vector<TakenMessage>& taken_messages();
+const std::vector<ShownWindow>&  shown_windows();
+
 } // namespace Slic3r::GUI::JusPrin::Workspace
