    // PROTOTYPE scenario (--orca-messages <directory>), not for landing.
    // Included inside class Scenario after the dialog routing scenario, whose
    // tool runner and dialog witness helpers it uses.
    //
    // Each case makes OrcaSlicer say something through its real code and
    // reads two things: which of its windows opened (the dialog witness), and
    // what the JusPrin view took instead, with the reason it carries. Run it
    // twice: with JUSPRIN_ORCA_MESSAGES=off the view takes nothing, which is
    // the app as it is today; without it the prototype is on.

    std::size_t m_om_taken_mark{0};
    std::size_t m_om_opened_mark{0};
    std::size_t m_om_shown_mark{0};
    bool        m_om_went{false};
    std::string m_om_other_printer;

    void om_mark()
    {
        m_om_taken_mark  = Workspace::taken_messages().size();
        m_om_opened_mark = g_dialog_witness->shown().size();
        m_om_shown_mark  = Workspace::shown_windows().size();
    }

    static std::string om_one_line(std::string text)
    {
        for (char& c : text)
            if (c == '\n' || c == '\r')
                c = ' ';
        return text.size() > 260 ? text.substr(0, 260) + "..." : text;
    }

    // Prints what happened since the mark. Returns the taken message with
    // `words` in it, if any, and whether a window with `words` opened.
    const Workspace::TakenMessage* om_report(const std::string& name, const std::string& words, bool& opened)
    {
        std::cerr << "HARNESS MESSAGE CASE " << name << " prototype=" << (Workspace::view_takes_messages() ? "on" : "off") << '\n';
        const Workspace::TakenMessage* match = nullptr;
        const auto&                    taken = Workspace::taken_messages();
        for (std::size_t index = m_om_taken_mark; index < taken.size(); ++index) {
            const Workspace::TakenMessage& message = taken[index];
            std::cerr << "HARNESS MESSAGE TAKEN from=" << Workspace::from_name(message.from) << " cause=" << Workspace::cause_name(message.cause.kind)
                      << " printer='" << message.cause.printer << "' detail='" << message.cause.detail << "' title='" << message.title
                      << "' text='" << om_one_line(message.text) << "'\n";
            if (match == nullptr && (message.text.find(words) != std::string::npos || message.title.find(words) != std::string::npos))
                match = &message;
        }
        opened = false;
        for (const std::string& dialog : dialogs_shown_since(m_om_opened_mark)) {
            std::cerr << "HARNESS MESSAGE OPENED [" << om_one_line(dialog) << "]\n";
            opened = opened || dialog.find(words) != std::string::npos;
        }
        const auto& shown = Workspace::shown_windows();
        for (std::size_t index = m_om_shown_mark; index < shown.size(); ++index)
            std::cerr << "HARNESS MESSAGE LET THROUGH title='" << shown[index].title << "' class=" << shown[index].window_class << " why='"
                      << shown[index].why << "'\n";
        return match;
    }

    // A message the view should take: today OrcaSlicer's window opens; with
    // the prototype no window opens and the message is taken with its cause.
    void om_taken_case(const std::string& name, const std::string& words, const char* from, const char* cause, const std::string& printer = {})
    {
        bool                           opened = false;
        const Workspace::TakenMessage* match  = om_report(name, words, opened);
        if (!Workspace::view_takes_messages()) {
            check(opened, name + "_today_orca_window_opens");
            return;
        }
        check(!opened, name + "_no_orca_window_opens");
        check(match != nullptr, name + "_is_taken");
        if (match == nullptr)
            return;
        check(std::string(Workspace::from_name(match->from)) == from, name + "_taken_at_the_expected_point");
        check(std::string(Workspace::cause_name(match->cause.kind)) == cause, name + "_keeps_its_cause");
        if (!printer.empty())
            check(match->cause.printer == printer, name + "_names_the_printer");
    }

    // A window that must open either way.
    void om_shown_case(const std::string& name, const std::string& words)
    {
        bool                           opened = false;
        const Workspace::TakenMessage* match  = om_report(name, words, opened);
        check(opened, name + "_opens");
        check(match == nullptr, name + "_is_not_taken");
    }

    // No modal window is open. The witness closes one window per tick and the
    // oldest first, so a case starts only once the last case's are gone.
    bool om_quiet()
    {
        for (const wxWindow* window : wxTopLevelWindows)
            if (const auto* dialog = dynamic_cast<const wxDialog*>(window); dialog != nullptr && dialog->IsShown() && dialog->IsModal())
                return false;
        return orca_caught_up();
    }
    std::function<bool()> om_quiet_and(std::function<bool()> also = {})
    {
        return [self = shared_from_this(), also] { return (!also || also()) && self->om_quiet(); };
    }

    // Writes an STL of boxes and imports it as the AI's tool does.
    void om_import_boxes(const std::string& name, bool second_shell)
    {
        const std::string path = (fs::path(data_dir()) / name).string();
        {
            std::ofstream out(path);
            out << "solid shells\n";
            write_box(out, {-10, -10, 0}, {10, 10, 10});
            if (second_shell)
                write_box(out, {-10, -10, 20}, {10, 10, 30});
            out << "endsolid shells\n";
        }
        nlohmann::json import = session_arguments();
        import["path"]        = path;
        run_dialog_tool("object_import_file", import);
    }

    bool om_printer_dirty() const { return wxGetApp().preset_bundle->printers.current_is_dirty(); }

    // Leaves the selected printer preset with an unsaved edit, as a person's
    // or the AI's change does.
    void om_edit_printer_setting(const std::string& value)
    {
        const std::string printer = wxGetApp().preset_bundle->printers.get_edited_preset().name;
        patch_settings({{"scope", "printer"}, {"target", {{"preset", printer}}}, {"changes", {{"printable_height", value}}}});
        std::cerr << "HARNESS MESSAGE NOTE printer '" << printer << "' dirty=" << om_printer_dirty() << '\n';
    }

    void begin_orca_messages()
    {
        check(g_dialog_witness != nullptr, "dialog_witness_installed");
        if (g_dialog_witness == nullptr)
            return finish();
        g_dialog_witness->start();
        std::cerr << "HARNESS MESSAGE PROTOTYPE " << (Workspace::view_takes_messages() ? "on" : "off") << '\n';
        connect_fixture_to_fake_printer([self = shared_from_this()] { self->run_orca_messages(); });
    }

    void run_orca_messages()
    {
        auto  self  = shared_from_this();
        auto& steps = m_issue_steps;
        const std::string device = JUSPRIN_FAKE_BAMBU_DEV_ID;

        // -- The printer answers "project_file" with FAIL. OrcaSlicer's
        //    MachineObject::parse_json calls GUI_App::push_notification with
        //    the printer, which queues the box titled Info. ------------------
        steps.push_back({"om_print_job_refused", [self, device] {
            self->om_mark();
            MachineObject* printer = wxGetApp().getDeviceManager()->get_my_machine(device);
            self->check(printer != nullptr, "om_fake_printer_known_to_orca");
            if (printer != nullptr)
                printer->parse_json("lan", R"({"print":{"command":"project_file","result":"FAIL","sequence_id":"0"}})");
        }, self->om_quiet_and(), [self, device] { self->om_taken_case("print_job_refused", "Failed to start print job", "printer_notification", "printer_message", device); }});

        // -- The network plug-in tells the app to update. It names no
        //    printer: GUI_App::process_network_msg handles these messages
        //    only when the device id is empty, and opens a box with only OK
        //    and no parent. -------------------------------------------------
        steps.push_back({"om_plugin_message", [self] {
            self->om_mark();
            wxGetApp().process_network_msg("", "update_studio");
        }, self->om_quiet_and(), [self] {
            self->om_taken_case("plugin_message", "try updating", "box", "plugin_message");
            if (Workspace::view_takes_messages())
                for (std::size_t index = self->m_om_taken_mark; index < Workspace::taken_messages().size(); ++index)
                    self->check(Workspace::taken_messages()[index].cause.detail == "update_studio", "plugin_message_keeps_the_plug_ins_code");
        }});

        // -- The printer refuses the connection with code -1: the popup of
        //    the second held commit. ---------------------------------------
        const auto connect_started = std::make_shared<std::chrono::steady_clock::time_point>();
        steps.push_back({"om_connect_failed", [self, device, connect_started] {
            self->om_mark();
            const auto fake = std::dynamic_pointer_cast<FakeBambuAgent>(wxGetApp().getAgent()->get_printer_agent());
            self->check(fake != nullptr, "om_fake_agent");
            if (fake == nullptr)
                return;
            // As the header's printer menu connects: the printer is selected
            // again and OrcaSlicer connects to its device.
            const std::string before = wxGetApp().preset_bundle->printers.get_edited_preset().name;
            wxGetApp().getDeviceManager()->set_selected_machine("");
            wxYield();
            fake->fail_next_connect("-1");
            *connect_started = std::chrono::steady_clock::now();
            self->check(SetupCommands::select_named_printer(*self->m_plater, kFakeFixturePrinter), "om_header_connect_selects_the_printer");
            std::cerr << "HARNESS MESSAGE NOTE printer before='" << before << "'\n";
        }, self->om_quiet_and([device, connect_started] {
            const auto last = Printers::last_connection_event(device);
            return last && last->kind == Printers::ConnectionEvent::Kind::Failed && last->at >= *connect_started;
        }), [self, device] { self->om_taken_case("connect_failed", "failed!", "app_dialog", "printer_connection", device); }});

        // -- An upload to a print host fails: a real job to a closed port.
        //    The queue's thread posts EVT_PRINTHOST_ERROR and
        //    PrintHostQueueDialog::on_error calls show_error. --------------
        const auto upload_from = std::make_shared<std::size_t>(0);
        steps.push_back({"om_host_upload_error", [self, upload_from] {
            self->om_mark();
            *upload_from = Workspace::taken_messages().size() + g_dialog_witness->shown().size();
            DynamicPrintConfig config = wxGetApp().preset_bundle->full_config();
            config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(htOctoPrint));
            config.set_key_value("print_host", new ConfigOptionString("127.0.0.1:9"));
            config.set_key_value("printhost_apikey", new ConfigOptionString("harness"));
            PrintHostJob job(&config);
            self->check(job.printhost != nullptr, "om_print_host_made");
            if (job.printhost == nullptr)
                return;
            job.upload_data.source_path = (fs::path(data_dir()) / "messages-one-shell.stl").string();
            { std::ofstream out(job.upload_data.source_path.string()); out << "solid shells\n"; write_box(out, {-10, -10, 0}, {10, 10, 10}); out << "endsolid shells\n"; }
            job.upload_data.upload_path = "orca-messages.gcode";
            job.upload_data.post_action = PrintHostPostUploadAction::None;
            // JusPrin's Print starts the recorder listening before any upload
            // is queued; so does this.
            installed_shell()->gcode_history()->listen_to_print_host_queue();
            wxGetApp().printhost_job_queue().enqueue(std::move(job));
        }, self->om_quiet_and([upload_from] { return Workspace::taken_messages().size() + g_dialog_witness->shown().size() > *upload_from; }),
        [self] { self->om_taken_case("host_upload_error", "Error uploading to print host", "error_box", "host_upload", "127.0.0.1:9"); }});

        // -- Split, as OrcaSlicer's own right-click menu runs it, on an object
        //    with one shell: "The selected object couldn't be split." No
        //    JusPrin code is at the source. ---------------------------------
        steps.push_back({"om_split_refused", [self] {
            self->om_import_boxes("messages-one-shell.stl", false);
            self->om_mark();
            self->check(self->m_plater->select_object(self->m_plater->model().objects.size() - 1), "om_object_selected");
            self->m_plater->split_object();
        }, self->om_quiet_and(), [self] {
            self->om_taken_case("split_refused", "couldn't be split", "box", "none");
            if (!Workspace::view_takes_messages())
                return;
            // Shown where OrcaSlicer's own notices of an outcome are shown.
            installed_shell()->print_issues()->refresh_now();
            bool on_canvas = false;
            for (const PrintIssues::Notice& notice : installed_shell()->print_issues()->snapshot().notices) {
                std::cerr << "HARNESS MESSAGE NOTICE kind=" << notice.kind_name << " text='" << om_one_line(notice.text) << "'\n";
                on_canvas = on_canvas || notice.text.find("couldn't be split") != std::string::npos;
            }
            self->check(on_canvas, "split_refused_shows_as_a_canvas_confirmation");
        }});

        // -- The same command on two shells, one floating: OrcaSlicer asks
        //    "Disable Auto-Drop...?". A question stays the person's. --------
        steps.push_back({"om_split_question", [self] {
            self->om_import_boxes("messages-two-shells.stl", true);
            self->om_mark();
            self->check(self->m_plater->select_object(self->m_plater->model().objects.size() - 1), "om_object_selected");
            self->m_plater->split_object();
        }, self->om_quiet_and(), [self] { self->om_shown_case("split_question", "Auto-Drop"); }});

        // -- OrcaSlicer's settings window is open and its code reports a bad
        //    value the way Field.cpp does. The box belongs with that window. -
        steps.push_back({"om_message_in_settings_window", [self] {
            ParamsDialog* settings = wxGetApp().params_dialog();
            self->check(settings != nullptr, "om_settings_window_exists");
            if (settings == nullptr)
                return;
            settings->Popup();
            self->om_mark();
            Slic3r::GUI::show_error(settings, _L("Invalid numeric."));
        }, self->om_quiet_and(), [self] {
            self->om_shown_case("message_in_settings_window", "Invalid numeric");
            if (ParamsDialog* settings = wxGetApp().params_dialog())
                settings->Hide();
        }});

        // -- File > Import: Plater::add_file opens the file open's scope and
        //    then the picker. Today the scope's listener cancels the picker
        //    before it is drawn. --------------------------------------------
        steps.push_back({"om_import_picker", [self] {
            self->om_mark();
            self->m_plater->add_file();
        }, self->om_quiet_and(), [self] {
            // The system's picker has no title or text of wx's to read: any
            // window that reached the witness in this step is the picker.
            bool opened = false;
            self->om_report("import_picker", "Choose one or more files", opened);
            const std::size_t reached = self->dialogs_shown_since(self->m_om_opened_mark).size();
            if (Workspace::view_takes_messages())
                self->check(reached == 1, "import_picker_reaches_the_person");
            else
                self->check(reached == 0, "import_picker_today_is_cancelled_unseen");
        }});

        // -- A switch of printer with an unsaved setting change, through the
        //    call the header's printer menu makes. --------------------------
        steps.push_back({"om_edit_before_switch", [self] { self->om_edit_printer_setting("171"); }, {}, {}});
        steps.push_back({"om_switch_printer", [self] {
            PresetBundle&     bundle  = *wxGetApp().preset_bundle;
            const std::string current = bundle.printers.get_edited_preset().name;
            for (const Preset& preset : bundle.printers)
                if (preset.is_visible && !preset.is_default && preset.name != current) {
                    self->m_om_other_printer = preset.name;
                    break;
                }
            self->check(!self->m_om_other_printer.empty() && self->om_printer_dirty(), "om_switch_has_an_edit_and_another_printer");
            self->om_mark();
            SetupCommands::select_printer_preset(*self->m_plater, self->m_om_other_printer);
        }, self->om_quiet_and(), [self] {
            bool                           opened   = false;
            const Workspace::TakenMessage* match    = self->om_report("switch_printer", "Transfer or discard", opened);
            const bool                     switched = wxGetApp().preset_bundle->printers.get_edited_preset().name == self->m_om_other_printer;
            std::cerr << "HARNESS MESSAGE NOTE switched=" << switched << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "switch_printer_today_orca_asks");
                return;
            }
            self->check(!opened, "switch_printer_asks_nothing");
            self->check(match != nullptr, "switch_printer_version_saved_and_edits_dropped");
            self->check(switched && !self->om_printer_dirty(), "switch_printer_switched");
        }});

        // -- The same question on the path the import window and the setup
        //    wizard use, which reads the dialog's recorded choice. ----------
        steps.push_back({"om_edit_before_reload", [self] { self->om_edit_printer_setting("172"); }, {}, {}});
        steps.push_back({"om_unsaved_before_reload", [self] {
            self->check(self->om_printer_dirty(), "om_reload_has_an_edit");
            self->om_mark();
            self->m_om_went = wxGetApp().check_and_save_current_preset_changes(_L("Import from OrcaSlicer"), _L("Importing these printers loads their profiles."), false);
        }, self->om_quiet_and(), [self] {
            bool                           opened = false;
            const Workspace::TakenMessage* match  = self->om_report("unsaved_before_reload", "unsaved changes", opened);
            std::cerr << "HARNESS MESSAGE NOTE went_on=" << self->m_om_went << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "unsaved_before_reload_today_orca_asks");
                return;
            }
            self->check(!opened, "unsaved_before_reload_asks_nothing");
            self->check(match != nullptr && self->m_om_went && !self->om_printer_dirty(), "unsaved_before_reload_goes_on_with_edits_dropped");
        }});

        // -- Code switches the main window to a page the JusPrin view hides,
        //    with the call MainFrame::jump_to_monitor and the "Go to" keys
        //    make. The Calibration page stands in for the Device page, which
        //    is not in the page list without the Bambu plug-in. -------------
        steps.push_back({"om_page_switch", [self] {
            self->om_mark();
            wxGetApp().mainframe->m_tabpanel->SelectPageByName(TAB_ID_CALIBRATION);
        }, self->om_quiet_and(), [self] {
            bool              opened = false;
            const auto*       match  = self->om_report("page_switch", TAB_ID_CALIBRATION, opened);
            const std::string page   = wxGetApp().mainframe->m_tabpanel->GetSelectedPageName().ToUTF8().data();
            std::cerr << "HARNESS MESSAGE NOTE page_now=" << page << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(page == TAB_ID_CALIBRATION, "page_switch_today_shows_a_hidden_orca_page");
                wxGetApp().mainframe->select_tab(wxString(TAB_ID_PREPARE));
                return;
            }
            self->check(page == TAB_ID_PREPARE && match != nullptr, "page_switch_is_refused");
        }});

        // -- The key that steps through OrcaSlicer's pages (Ctrl+Tab), pressed
        //    three times on the main window. --------------------------------
        const auto pages = std::make_shared<std::string>();
        steps.push_back({"om_ctrl_tab", [self, pages] {
            self->om_mark();
            for (int press = 0; press < 3; ++press) {
                wxKeyEvent key(wxEVT_CHAR_HOOK);
                key.m_keyCode = WXK_TAB;
#ifdef __APPLE__
                key.SetRawControlDown(true);
#else
                key.SetControlDown(true);
#endif
                key.SetEventObject(wxGetApp().mainframe);
                wxGetApp().mainframe->GetEventHandler()->ProcessEvent(key);
                *pages += std::string(wxGetApp().mainframe->m_tabpanel->GetSelectedPageName().ToUTF8().data()) + " ";
            }
        }, self->om_quiet_and(), [self, pages] {
            bool opened = false;
            self->om_report("ctrl_tab", "", opened);
            std::cerr << "HARNESS MESSAGE NOTE pages_after_each_press=" << *pages << '\n';
            const bool hidden_page = pages->find(TAB_ID_PREVIEW) != std::string::npos || pages->find(TAB_ID_MONITOR) != std::string::npos ||
                                     pages->find(TAB_ID_CALIBRATION) != std::string::npos || pages->find(TAB_ID_MULTI_DEVICE) != std::string::npos;
            if (Workspace::view_takes_messages())
                self->check(!hidden_page, "ctrl_tab_reaches_no_hidden_page");
            else
                self->check(hidden_page, "ctrl_tab_today_reaches_a_hidden_page");
            wxGetApp().mainframe->select_tab(wxString(TAB_ID_PREPARE));
        }});

        // -- A start G-code the placeholder parser refuses: a critical slicing
        //    error after slice_start has returned. Plater's handler of the
        //    finished slice calls show_error. --------------------------------
        steps.push_back({"om_slice_error_setup", [self] {
            const std::string printer = wxGetApp().preset_bundle->printers.get_edited_preset().name;
            self->patch_settings({{"scope", "printer"}, {"target", {{"preset", printer}}}, {"changes", {{"machine_start_gcode", "{if}"}}}});
        }, {}, {}});
        steps.push_back({"om_slice_error", [self] {
            self->om_mark();
            self->m_slice_started = std::chrono::steady_clock::now();
            self->run_dialog_tool("slice_start", nlohmann::json::object());
        }, self->slice_ended(), [self] { self->om_taken_case("slice_error", "start_gcode", "error_box", "slice"); }});

        steps.push_back({"om_summary", [self] {
            std::cerr << "HARNESS MESSAGE SUMMARY taken=" << Workspace::taken_messages().size() << " let_through=" << Workspace::shown_windows().size()
                      << " opened=" << g_dialog_witness->shown().size() << '\n';
        }, {}, {}});

        run_issue_steps();
    }

toolUseResult.stdout:
    // PROTOTYPE scenario (--orca-messages <directory>), not for landing.
    // Included inside class Scenario after the dialog routing scenario, whose
    // tool runner and dialog witness helpers it uses.
    //
    // Each case makes OrcaSlicer say something through its real code and
    // reads two things: which of its windows opened (the dialog witness), and
    // what the JusPrin view took instead, with the reason it carries. Run it
    // twice: with JUSPRIN_ORCA_MESSAGES=off the view takes nothing, which is
    // the app as it is today; without it the prototype is on.

    std::size_t m_om_taken_mark{0};
    std::size_t m_om_opened_mark{0};
    std::size_t m_om_shown_mark{0};
    bool        m_om_went{false};
    std::string m_om_other_printer;

    void om_mark()
    {
        m_om_taken_mark  = Workspace::taken_messages().size();
        m_om_opened_mark = g_dialog_witness->shown().size();
        m_om_shown_mark  = Workspace::shown_windows().size();
    }

    static std::string om_one_line(std::string text)
    {
        for (char& c : text)
            if (c == '\n' || c == '\r')
                c = ' ';
        return text.size() > 260 ? text.substr(0, 260) + "..." : text;
    }

    // Prints what happened since the mark. Returns the taken message with
    // `words` in it, if any, and whether a window with `words` opened.
    const Workspace::TakenMessage* om_report(const std::string& name, const std::string& words, bool& opened)
    {
        std::cerr << "HARNESS MESSAGE CASE " << name << " prototype=" << (Workspace::view_takes_messages() ? "on" : "off") << '\n';
        const Workspace::TakenMessage* match = nullptr;
        const auto&                    taken = Workspace::taken_messages();
        for (std::size_t index = m_om_taken_mark; index < taken.size(); ++index) {
            const Workspace::TakenMessage& message = taken[index];
            std::cerr << "HARNESS MESSAGE TAKEN from=" << Workspace::from_name(message.from) << " cause=" << Workspace::cause_name(message.cause.kind)
                      << " printer='" << message.cause.printer << "' detail='" << message.cause.detail << "' title='" << message.title
                      << "' text='" << om_one_line(message.text) << "'\n";
            if (match == nullptr && (message.text.find(words) != std::string::npos || message.title.find(words) != std::string::npos))
                match = &message;
        }
        opened = false;
        for (const std::string& dialog : dialogs_shown_since(m_om_opened_mark)) {
            std::cerr << "HARNESS MESSAGE OPENED [" << om_one_line(dialog) << "]\n";
            opened = opened || dialog.find(words) != std::string::npos;
        }
        const auto& shown = Workspace::shown_windows();
        for (std::size_t index = m_om_shown_mark; index < shown.size(); ++index)
            std::cerr << "HARNESS MESSAGE LET THROUGH title='" << shown[index].title << "' class=" << shown[index].window_class << " why='"
                      << shown[index].why << "'\n";
        return match;
    }

    // A message the view should take: today OrcaSlicer's window opens; with
    // the prototype no window opens and the message is taken with its cause.
    void om_taken_case(const std::string& name, const std::string& words, const char* from, const char* cause, const std::string& printer = {})
    {
        bool                           opened = false;
        const Workspace::TakenMessage* match  = om_report(name, words, opened);
        if (!Workspace::view_takes_messages()) {
            check(opened, name + "_today_orca_window_opens");
            return;
        }
        check(!opened, name + "_no_orca_window_opens");
        check(match != nullptr, name + "_is_taken");
        if (match == nullptr)
            return;
        check(std::string(Workspace::from_name(match->from)) == from, name + "_taken_at_the_expected_point");
        check(std::string(Workspace::cause_name(match->cause.kind)) == cause, name + "_keeps_its_cause");
        if (!printer.empty())
            check(match->cause.printer == printer, name + "_names_the_printer");
    }

    // A window that must open either way.
    void om_shown_case(const std::string& name, const std::string& words)
    {
        bool                           opened = false;
        const Workspace::TakenMessage* match  = om_report(name, words, opened);
        check(opened, name + "_opens");
        check(match == nullptr, name + "_is_not_taken");
    }

    // No modal window is open. The witness closes one window per tick and the
    // oldest first, so a case starts only once the last case's are gone.
    bool om_quiet()
    {
        for (const wxWindow* window : wxTopLevelWindows)
            if (const auto* dialog = dynamic_cast<const wxDialog*>(window); dialog != nullptr && dialog->IsShown() && dialog->IsModal())
                return false;
        return orca_caught_up();
    }
    std::function<bool()> om_quiet_and(std::function<bool()> also = {})
    {
        return [self = shared_from_this(), also] { return (!also || also()) && self->om_quiet(); };
    }

    // Writes an STL of boxes and imports it as the AI's tool does.
    void om_import_boxes(const std::string& name, bool second_shell)
    {
        const std::string path = (fs::path(data_dir()) / name).string();
        {
            std::ofstream out(path);
            out << "solid shells\n";
            write_box(out, {-10, -10, 0}, {10, 10, 10});
            if (second_shell)
                write_box(out, {-10, -10, 20}, {10, 10, 30});
            out << "endsolid shells\n";
        }
        nlohmann::json import = session_arguments();
        import["path"]        = path;
        run_dialog_tool("object_import_file", import);
    }

    bool om_printer_dirty() const { return wxGetApp().preset_bundle->printers.current_is_dirty(); }

    // Leaves the selected printer preset with an unsaved edit, as a person's
    // or the AI's change does.
    void om_edit_printer_setting(const std::string& value)
    {
        const std::string printer = wxGetApp().preset_bundle->printers.get_edited_preset().name;
        patch_settings({{"scope", "printer"}, {"target", {{"preset", printer}}}, {"changes", {{"printable_height", value}}}});
        std::cerr << "HARNESS MESSAGE NOTE printer '" << printer << "' dirty=" << om_printer_dirty() << '\n';
    }

    void begin_orca_messages()
    {
        check(g_dialog_witness != nullptr, "dialog_witness_installed");
        if (g_dialog_witness == nullptr)
            return finish();
        g_dialog_witness->start();
        std::cerr << "HARNESS MESSAGE PROTOTYPE " << (Workspace::view_takes_messages() ? "on" : "off") << '\n';
        connect_fixture_to_fake_printer([self = shared_from_this()] { self->run_orca_messages(); });
    }

    void run_orca_messages()
    {
        auto  self  = shared_from_this();
        auto& steps = m_issue_steps;
        const std::string device = JUSPRIN_FAKE_BAMBU_DEV_ID;

        // -- The printer answers "project_file" with FAIL. OrcaSlicer's
        //    MachineObject::parse_json calls GUI_App::push_notification with
        //    the printer, which queues the box titled Info. ------------------
        steps.push_back({"om_print_job_refused", [self, device] {
            self->om_mark();
            MachineObject* printer = wxGetApp().getDeviceManager()->get_my_machine(device);
            self->check(printer != nullptr, "om_fake_printer_known_to_orca");
            if (printer != nullptr)
                printer->parse_json("lan", R"({"print":{"command":"project_file","result":"FAIL","sequence_id":"0"}})");
        }, self->om_quiet_and(), [self, device] { self->om_taken_case("print_job_refused", "Failed to start print job", "printer_notification", "printer_message", device); }});

        // -- The network plug-in tells the app to update. It names no
        //    printer: GUI_App::process_network_msg handles these messages
        //    only when the device id is empty, and opens a box with only OK
        //    and no parent. -------------------------------------------------
        steps.push_back({"om_plugin_message", [self] {
            self->om_mark();
            wxGetApp().process_network_msg("", "update_studio");
        }, self->om_quiet_and(), [self] {
            self->om_taken_case("plugin_message", "try updating", "box", "plugin_message");
            if (Workspace::view_takes_messages())
                for (std::size_t index = self->m_om_taken_mark; index < Workspace::taken_messages().size(); ++index)
                    self->check(Workspace::taken_messages()[index].cause.detail == "update_studio", "plugin_message_keeps_the_plug_ins_code");
        }});

        // -- The printer refuses the connection with code -1: the popup of
        //    the second held commit. ---------------------------------------
        const auto connect_started = std::make_shared<std::chrono::steady_clock::time_point>();
        steps.push_back({"om_connect_failed", [self, device, connect_started] {
            self->om_mark();
            const auto fake = std::dynamic_pointer_cast<FakeBambuAgent>(wxGetApp().getAgent()->get_printer_agent());
            self->check(fake != nullptr, "om_fake_agent");
            if (fake == nullptr)
                return;
            // As the header's printer menu connects: the printer is selected
            // again and OrcaSlicer connects to its device.
            const std::string before = wxGetApp().preset_bundle->printers.get_edited_preset().name;
            wxGetApp().getDeviceManager()->set_selected_machine("");
            wxYield();
            fake->fail_next_connect("-1");
            *connect_started = std::chrono::steady_clock::now();
            self->check(SetupCommands::select_named_printer(*self->m_plater, kFakeFixturePrinter), "om_header_connect_selects_the_printer");
            std::cerr << "HARNESS MESSAGE NOTE printer before='" << before << "'\n";
        }, self->om_quiet_and([device, connect_started] {
            const auto last = Printers::last_connection_event(device);
            return last && last->kind == Printers::ConnectionEvent::Kind::Failed && last->at >= *connect_started;
        }), [self, device] { self->om_taken_case("connect_failed", "failed!", "app_dialog", "printer_connection", device); }});

        // -- An upload to a print host fails: a real job to a closed port.
        //    The queue's thread posts EVT_PRINTHOST_ERROR and
        //    PrintHostQueueDialog::on_error calls show_error. --------------
        const auto upload_from = std::make_shared<std::size_t>(0);
        steps.push_back({"om_host_upload_error", [self, upload_from] {
            self->om_mark();
            *upload_from = Workspace::taken_messages().size() + g_dialog_witness->shown().size();
            DynamicPrintConfig config = wxGetApp().preset_bundle->full_config();
            config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(htOctoPrint));
            config.set_key_value("print_host", new ConfigOptionString("127.0.0.1:9"));
            config.set_key_value("printhost_apikey", new ConfigOptionString("harness"));
            PrintHostJob job(&config);
            self->check(job.printhost != nullptr, "om_print_host_made");
            if (job.printhost == nullptr)
                return;
            job.upload_data.source_path = (fs::path(data_dir()) / "messages-one-shell.stl").string();
            { std::ofstream out(job.upload_data.source_path.string()); out << "solid shells\n"; write_box(out, {-10, -10, 0}, {10, 10, 10}); out << "endsolid shells\n"; }
            job.upload_data.upload_path = "orca-messages.gcode";
            job.upload_data.post_action = PrintHostPostUploadAction::None;
            // JusPrin's Print starts the recorder listening before any upload
            // is queued; so does this.
            installed_shell()->gcode_history()->listen_to_print_host_queue();
            wxGetApp().printhost_job_queue().enqueue(std::move(job));
        }, self->om_quiet_and([upload_from] { return Workspace::taken_messages().size() + g_dialog_witness->shown().size() > *upload_from; }),
        [self] { self->om_taken_case("host_upload_error", "Error uploading to print host", "error_box", "host_upload", "127.0.0.1:9"); }});

        // -- Split, as OrcaSlicer's own right-click menu runs it, on an object
        //    with one shell: "The selected object couldn't be split." No
        //    JusPrin code is at the source. ---------------------------------
        steps.push_back({"om_split_refused", [self] {
            self->om_import_boxes("messages-one-shell.stl", false);
            self->om_mark();
            self->check(self->m_plater->select_object(self->m_plater->model().objects.size() - 1), "om_object_selected");
            self->m_plater->split_object();
        }, self->om_quiet_and(), [self] {
            self->om_taken_case("split_refused", "couldn't be split", "box", "none");
            if (!Workspace::view_takes_messages())
                return;
            // Shown where OrcaSlicer's own notices of an outcome are shown.
            installed_shell()->print_issues()->refresh_now();
            bool on_canvas = false;
            for (const PrintIssues::Notice& notice : installed_shell()->print_issues()->snapshot().notices) {
                std::cerr << "HARNESS MESSAGE NOTICE kind=" << notice.kind_name << " text='" << om_one_line(notice.text) << "'\n";
                on_canvas = on_canvas || notice.text.find("couldn't be split") != std::string::npos;
            }
            self->check(on_canvas, "split_refused_shows_as_a_canvas_confirmation");
        }});

        // -- The same command on two shells, one floating: OrcaSlicer asks
        //    "Disable Auto-Drop...?". A question stays the person's. --------
        steps.push_back({"om_split_question", [self] {
            self->om_import_boxes("messages-two-shells.stl", true);
            self->om_mark();
            self->check(self->m_plater->select_object(self->m_plater->model().objects.size() - 1), "om_object_selected");
            self->m_plater->split_object();
        }, self->om_quiet_and(), [self] { self->om_shown_case("split_question", "Auto-Drop"); }});

        // -- OrcaSlicer's settings window is open and its code reports a bad
        //    value the way Field.cpp does. The box belongs with that window. -
        steps.push_back({"om_message_in_settings_window", [self] {
            ParamsDialog* settings = wxGetApp().params_dialog();
            self->check(settings != nullptr, "om_settings_window_exists");
            if (settings == nullptr)
                return;
            settings->Popup();
            self->om_mark();
            Slic3r::GUI::show_error(settings, _L("Invalid numeric."));
        }, self->om_quiet_and(), [self] {
            self->om_shown_case("message_in_settings_window", "Invalid numeric");
            if (ParamsDialog* settings = wxGetApp().params_dialog())
                settings->Hide();
        }});

        // -- File > Import: Plater::add_file opens the file open's scope and
        //    then the picker. Today the scope's listener cancels the picker
        //    before it is drawn. --------------------------------------------
        steps.push_back({"om_import_picker", [self] {
            self->om_mark();
            self->m_plater->add_file();
        }, self->om_quiet_and(), [self] {
            // The system's picker has no title or text of wx's to read: any
            // window that reached the witness in this step is the picker.
            bool opened = false;
            self->om_report("import_picker", "Choose one or more files", opened);
            const std::size_t reached = self->dialogs_shown_since(self->m_om_opened_mark).size();
            if (Workspace::view_takes_messages())
                self->check(reached == 1, "import_picker_reaches_the_person");
            else
                self->check(reached == 0, "import_picker_today_is_cancelled_unseen");
        }});

        // -- A switch of printer with an unsaved setting change, through the
        //    call the header's printer menu makes. --------------------------
        steps.push_back({"om_edit_before_switch", [self] { self->om_edit_printer_setting("171"); }, {}, {}});
        steps.push_back({"om_switch_printer", [self] {
            PresetBundle&     bundle  = *wxGetApp().preset_bundle;
            const std::string current = bundle.printers.get_edited_preset().name;
            for (const Preset& preset : bundle.printers)
                if (preset.is_visible && !preset.is_default && preset.name != current) {
                    self->m_om_other_printer = preset.name;
                    break;
                }
            self->check(!self->m_om_other_printer.empty() && self->om_printer_dirty(), "om_switch_has_an_edit_and_another_printer");
            self->om_mark();
            SetupCommands::select_printer_preset(*self->m_plater, self->m_om_other_printer);
        }, self->om_quiet_and(), [self] {
            bool                           opened   = false;
            const Workspace::TakenMessage* match    = self->om_report("switch_printer", "Transfer or discard", opened);
            const bool                     switched = wxGetApp().preset_bundle->printers.get_edited_preset().name == self->m_om_other_printer;
            std::cerr << "HARNESS MESSAGE NOTE switched=" << switched << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "switch_printer_today_orca_asks");
                return;
            }
            self->check(!opened, "switch_printer_asks_nothing");
            self->check(match != nullptr, "switch_printer_version_saved_and_edits_dropped");
            self->check(switched && !self->om_printer_dirty(), "switch_printer_switched");
        }});

        // -- The same question on the path the import window and the setup
        //    wizard use, which reads the dialog's recorded choice. ----------
        steps.push_back({"om_edit_before_reload", [self] { self->om_edit_printer_setting("172"); }, {}, {}});
        steps.push_back({"om_unsaved_before_reload", [self] {
            self->check(self->om_printer_dirty(), "om_reload_has_an_edit");
            self->om_mark();
            self->m_om_went = wxGetApp().check_and_save_current_preset_changes(_L("Import from OrcaSlicer"), _L("Importing these printers loads their profiles."), false);
        }, self->om_quiet_and(), [self] {
            bool                           opened = false;
            const Workspace::TakenMessage* match  = self->om_report("unsaved_before_reload", "unsaved changes", opened);
            std::cerr << "HARNESS MESSAGE NOTE went_on=" << self->m_om_went << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "unsaved_before_reload_today_orca_asks");
                return;
            }
            self->check(!opened, "unsaved_before_reload_asks_nothing");
            self->check(match != nullptr && self->m_om_went && !self->om_printer_dirty(), "unsaved_before_reload_goes_on_with_edits_dropped");
        }});

        // -- Code switches the main window to a page the JusPrin view hides,
        //    with the call MainFrame::jump_to_monitor and the "Go to" keys
        //    make. The Calibration page stands in for the Device page, which
        //    is not in the page list without the Bambu plug-in. -------------
        steps.push_back({"om_page_switch", [self] {
            self->om_mark();
            wxGetApp().mainframe->m_tabpanel->SelectPageByName(TAB_ID_CALIBRATION);
        }, self->om_quiet_and(), [self] {
            bool              opened = false;
            const auto*       match  = self->om_report("page_switch", TAB_ID_CALIBRATION, opened);
            const std::string page   = wxGetApp().mainframe->m_tabpanel->GetSelectedPageName().ToUTF8().data();
            std::cerr << "HARNESS MESSAGE NOTE page_now=" << page << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(page == TAB_ID_CALIBRATION, "page_switch_today_shows_a_hidden_orca_page");
                wxGetApp().mainframe->select_tab(wxString(TAB_ID_PREPARE));
                return;
            }
            self->check(page == TAB_ID_PREPARE && match != nullptr, "page_switch_is_refused");
        }});

        // -- The key that steps through OrcaSlicer's pages (Ctrl+Tab), pressed
        //    three times on the main window. --------------------------------
        const auto pages = std::make_shared<std::string>();
        steps.push_back({"om_ctrl_tab", [self, pages] {
            self->om_mark();
            for (int press = 0; press < 3; ++press) {
                wxKeyEvent key(wxEVT_CHAR_HOOK);
                key.m_keyCode = WXK_TAB;
#ifdef __APPLE__
                key.SetRawControlDown(true);
#else
                key.SetControlDown(true);
#endif
                key.SetEventObject(wxGetApp().mainframe);
                wxGetApp().mainframe->GetEventHandler()->ProcessEvent(key);
                *pages += std::string(wxGetApp().mainframe->m_tabpanel->GetSelectedPageName().ToUTF8().data()) + " ";
            }
        }, self->om_quiet_and(), [self, pages] {
            bool opened = false;
            self->om_report("ctrl_tab", "", opened);
            std::cerr << "HARNESS MESSAGE NOTE pages_after_each_press=" << *pages << '\n';
            const bool hidden_page = pages->find(TAB_ID_PREVIEW) != std::string::npos || pages->find(TAB_ID_MONITOR) != std::string::npos ||
                                     pages->find(TAB_ID_CALIBRATION) != std::string::npos || pages->find(TAB_ID_MULTI_DEVICE) != std::string::npos;
            if (Workspace::view_takes_messages())
                self->check(!hidden_page, "ctrl_tab_reaches_no_hidden_page");
            else
                self->check(hidden_page, "ctrl_tab_today_reaches_a_hidden_page");
            wxGetApp().mainframe->select_tab(wxString(TAB_ID_PREPARE));
        }});

        // -- A start G-code the placeholder parser refuses: a critical slicing
        //    error after slice_start has returned. Plater's handler of the
        //    finished slice calls show_error. --------------------------------
        steps.push_back({"om_slice_error_setup", [self] {
            const std::string printer = wxGetApp().preset_bundle->printers.get_edited_preset().name;
            self->patch_settings({{"scope", "printer"}, {"target", {{"preset", printer}}}, {"changes", {{"machine_start_gcode", "{if}"}}}});
        }, {}, {}});
        steps.push_back({"om_slice_error", [self] {
            self->om_mark();
            self->m_slice_started = std::chrono::steady_clock::now();
            self->run_dialog_tool("slice_start", nlohmann::json::object());
        }, self->slice_ended(), [self] { self->om_taken_case("slice_error", "start_gcode", "error_box", "slice"); }});

        steps.push_back({"om_summary", [self] {
            std::cerr << "HARNESS MESSAGE SUMMARY taken=" << Workspace::taken_messages().size() << " let_through=" << Workspace::shown_windows().size()
                      << " opened=" << g_dialog_witness->shown().size() << '\n';
        }, {}, {}});

        run_issue_steps();
    }

