                wxKeyEvent key(wxEVT_CHAR_HOOK);
                key.m_keyCode = WXK_TAB;
#ifdef __APPLE__
                key.SetRawControlDown(true);
#else
                key.SetControlDown(true);
#endif
                key.SetEventObject(wxGetApp().mainframe);
                wxGetApp().mainframe->GetEventHandler()->ProcessEvent(key);
