            bool opened = false;
            self->om_report("ctrl_tab", "", opened);
            std::cerr << "HARNESS MESSAGE NOTE pages_after_each_press=" << *pages << '\n';
            const bool hidden_page = pages->find(TAB_ID_PREVIEW) != std::string::npos || pages->find(TAB_ID_MONITOR) != std::string::npos ||
