// Work the application ran outside the chat: a slice, an arrange, an export.
// While it runs the card carries its progress and, where the work can be
// stopped, a Cancel button; when it ends the same card says how. It is drawn
// from the tool card's own pieces, so it reads as the same kind of thing.

import type { ToolStateName, WorkInfo, WorkStateName } from '../bridge/protocol';
import { Progress } from './Progress';
import { ToolStatus } from './ToolActivityCard';
import { plural, t } from '@lingui/core/macro';
import { Trans } from '@lingui/react/macro';

interface Props {
  work: WorkInfo;
  // How many consecutive runs this card stands for; see `collapseWork`.
  times?: number;
  onCancel: (id: string) => void;
  readOnly?: boolean;
}

// The glyph each ending leads with. An interrupted run is shown as a failure
// would be: it did not finish.
const icons: Record<WorkStateName, ToolStateName> = {
  running: 'running',
  done: 'succeeded',
  cancelled: 'cancelled',
  failed: 'failed',
  interrupted: 'failed',
};

export function workStatus(work: WorkInfo): string {
  const total = work.progress?.total ?? 0;
  switch (work.state) {
    case 'running': {
      const words = work.detail || t`Running…`;
      return total > 0 ? `${words} · ${Math.round((100 * (work.progress?.current ?? 0)) / total)}%` : words;
    }
    case 'done':
      return t`Done`;
    case 'cancelled':
      return t`Cancelled`;
    case 'failed':
      return work.detail || t`It did not finish.`;
    case 'interrupted':
      return t`Interrupted when the project was closed`;
  }
}

// Consecutive runs that ended the same way and have the same title read as one
// card with a count, so slicing ten times is not ten cards. Nothing is merged
// in what is saved, and a run that is still going always stands alone.
export function collapseWork(entries: WorkInfo[]): { work: WorkInfo; times: number }[] {
  const cards: { work: WorkInfo; times: number }[] = [];
  for (const work of entries) {
    const last = cards[cards.length - 1];
    if (last && work.state !== 'running' && last.work.state === work.state && last.work.kind === work.kind &&
        last.work.title === work.title && last.work.detail === work.detail)
      cards[cards.length - 1] = { work, times: last.times + 1 };
    else cards.push({ work, times: 1 });
  }
  return cards;
}

export function WorkCard({ work, times = 1, onCancel, readOnly = false }: Props) {
  const running = work.state === 'running';
  const total = work.progress?.total ?? 0;
  const title = work.title;
  return (
    <div className={`tool-card state-${icons[work.state]}`} data-testid={`work-${work.id}`}>
      <div className="tool-title">
        {work.title}
        {times > 1 && <span className="work-times"> · {plural(times, { one: '# time', other: '# times' })}</span>}
      </div>
      <ToolStatus state={icons[work.state]}>{workStatus(work)}</ToolStatus>
      {running && (
        <>
          <Progress label={t`${title} progress`} value={total > 0 ? work.progress?.current : undefined}
            max={total > 0 ? total : undefined} />
          {work.cancellable && (
            <div className="tool-actions">
              <button disabled={readOnly} onClick={() => onCancel(work.id)}><Trans>Cancel</Trans></button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
#pragma once

// The work OrcaSlicer runs outside the chat, as it starts, moves on and ends:
// a slice, and whatever OrcaSlicer reports only as a "still running"
// notification (an arrange, an export, an upload). Each becomes one entry the
// chat keeps at the place it started.
//
// A slice is followed through OrcaSlicer's own events, which carry how far it
// is and how it ended. The rest is read from the notification list by the
// monitor: such a notification says that the work is running and nothing
// about how it ended, so one that goes is "done" unless its Cancel was
// pressed here.
//
// GUI thread only.

#include "PrintIssue.hpp"

#include <wx/event.h>

#include <functional>
#include <map>
#include <string>

namespace Slic3r {
class SlicingStatusEvent;
class SlicingProcessCompletedEvent;
namespace GUI {
class Plater;
}
} // namespace Slic3r

namespace Slic3r::GUI::JusPrin::PrintIssues {

class WorkFeed final
{
public:
    // Where the entries go: the chat host's three calls.
    struct Sink
    {
        std::function<std::string(const std::string& kind, const std::string& title, bool cancellable)> begin;
        std::function<void(const std::string& id, int current, int total, const std::string& detail)>   update;
        std::function<void(const std::string& id, const std::string& state, const std::string& detail)> finish;
    };

    WorkFeed(Plater& plater, Sink sink);
    ~WorkFeed();

    WorkFeed(const WorkFeed&) = delete;
    WorkFeed& operator=(const WorkFeed&) = delete;

    // The monitor read OrcaSlicer's state again.
    void sync(const PrintIssueSnapshot& snapshot);
    // The Cancel button of one entry.
    void cancel(const std::string& id);

private:
    struct Running
    {
        std::string id, title;
        bool        cancel_pressed{false};
    };

    void on_slicing_update(SlicingStatusEvent& event);
    void on_process_completed(SlicingProcessCompletedEvent& event);
    void end_slice(const std::string& state, const std::string& detail);

    Plater& m_plater;
    Sink    m_sink;
    // The one slice OrcaSlicer runs at a time.
    Running m_slice;
    // By notification kind, and by its words for the kinds OrcaSlicer holds
    // several of (uploads, downloads).
    std::map<std::string, Running> m_noticed;
};

} // namespace Slic3r::GUI::JusPrin::PrintIssues

