#pragma once

// Named printers: one machine a person owns, with a name they chose.
//
// OrcaSlicer has no printer object. Its "Physical Printer" dialog saves the
// connection settings into a user printer profile under a name the person
// types, and the collection that once held physical printers is never loaded.
// So a named printer here *is* an Orca user printer profile: the profile name
// is the printer's name, two machines of the same model are two profiles that
// inherit the same system profile, and everything Orca does with profiles --
// the settings tab, the sidebar combo, cloud sync -- keeps working unchanged.
//
// Every write goes through the upstream entry point that already performs it
// (Tab::save_preset, Tab::select_preset, Tab::delete_preset), so dirty
// tracking, cloud sync, and the plater refresh are upstream's. The one thing
// Orca does not store is which Bambu device a printer was added from; that
// link lives in the app config under kDeviceSection, keyed by device id.

#include "InstalledModels.hpp"
#include "PrinterOrigin.hpp"
#include "libslic3r/Preset.hpp"

#include <wx/string.h>

#include <string>
#include <vector>

namespace Slic3r::GUI { class Plater; }

namespace Slic3r::GUI::JusPrin::Printers {

struct NamedPrinter
{
    std::string name;      // the profile name, which is the printer's name
    std::string device_id; // the Bambu device it stands for; empty when none
    double      nozzle{0.};
    bool        selected{false};
};

// Every named printer, in the preset collection's order.
std::vector<NamedPrinter> named_printers();

// Saves the selected system printer profile as a new named printer and
// selects it. The name is `base_name`, or "base_name (2)" and so on when that
// is taken. `device_id`, when not empty, links the printer to that device; a
#pragma once

// Naming rules for a named printer: an Orca user printer profile that stands
// for one machine. Orca has no printer object of its own, so the profile's
// name is the printer's name, and it has to obey the rules Orca applies to any
// profile name.
//
// GUI-free and Orca-free so the rules are testable without a PresetBundle; the
// caller supplies what only the preset collection knows.

#include <functional>
#include <string>

namespace Slic3r::GUI::JusPrin::Printers {

using NamePredicate = std::function<bool(const std::string&)>;

enum class NameProblem
{
    None,
    Empty,
    EdgeSpace,        // leading or trailing space
    IllegalCharacter, // one of kIllegalNameCharacters
    Reserved,         // a name or suffix Orca keeps for itself
    Taken,            // another profile already has this name
};

// SavePresetDialog::Item::update's list. Upstream keeps its rules inline in
// the dialog, so they cannot be called; this is the same set, and the dialog
// is where a rebase looks for changes to it.
constexpr const char* kIllegalNameCharacters = "<>[]:/\\|?*\"";

// `reserved` answers for names Orca refuses (placeholders, preset aliases, the
// "(modified)" suffix); `taken` for names another profile already uses.
// Renaming a printer to its own name is not a problem, so `taken` must not
// report the printer being renamed.
NameProblem check_printer_name(const std::string& name, const NamePredicate& reserved, const NamePredicate& taken);

// `base` when it is free, otherwise "base (2)", "base (3)", ... A new printer
// never overwrites a profile; SavePresetDialog would, after a warning nobody
// sees when the name is chosen for them.
std::string first_free_printer_name(const std::string& base, const NamePredicate& taken);

// The name a copy of `preset` is saved under: "<preset> - Copy", the name
// SavePresetDialog offers for a copy of a preset Orca ships, or the first free
// one after it.
std::string copy_name(const std::string& preset, const NamePredicate& taken);

} // namespace Slic3r::GUI::JusPrin::Printers

