commit 311a3138012a59174a1beee0935638c2cbdb3548
Author: Kenneth Jiang <kenneth.jiang@gmail.com>
Date:   Thu Nov 12 11:53:09 2026 -0800

    Header printer menu: switching printers no longer asks to transfer or discard edits

    Picking another printer (or filament, or process) from the header menus went
    through Orca's Tab::select_preset, which shows "Transfer or discard changes"
    when the outgoing preset has unsaved edits. JusPrin never asks a person to
    save or discard; the earlier sweep removed that prompt from the AI tools,
    project open/close and the printer panel, but not from SetupCommands, which
    the header menus use.

    Every selection in SetupCommands now saves the project to its version history
    first (the shell supplies autosave's save_now), then drops the edits as Orca's
    Discard would. If there is no save step or the save fails, the edits stay and
    Orca asks as before, so nothing is lost. The drop and the selection share one
    project-state transaction, so the edit feed reports one preset switch.

    The shell harness's printer-menu mode switches printers from the header menu
    with an unsaved printer edit and checks that no dialog opens, the printer
    changes, the edit feed shows only a preset switch, and restoring the saved
    version brings the edit back. It also checks that when the project cannot be
    saved, Orca's prompt still appears and the edit is kept.

    Entire-Checkpoint: 01M78N4EP7E8PQ7QR2C82WM3JX

diff --git a/src/slic3r/GUI/JusPrin/Shell/SetupCommands.cpp b/src/slic3r/GUI/JusPrin/Shell/SetupCommands.cpp
index 71a7da6bf4..b1f22fe9bf 100644
--- a/src/slic3r/GUI/JusPrin/Shell/SetupCommands.cpp
+++ b/src/slic3r/GUI/JusPrin/Shell/SetupCommands.cpp
@@ -1,6 +1,7 @@
 #include "SetupCommands.hpp"
 #include "slic3r/GUI/JusPrin/Printers/HostLaneReader.hpp"
 #include "slic3r/GUI/JusPrin/Printers/NamedPrinters.hpp"
+#include "slic3r/GUI/JusPrin/Workspace/ProjectState.hpp"
 #include "slic3r/GUI/JusPrin/PrinterSetup/PrinterDiscovery.hpp"

 #include "libslic3r/PresetBundle.hpp"
@@ -45,6 +46,30 @@ wxString display_alias(const Preset& preset)

 namespace {

+std::function<bool()>& history_save_step()
+{
+    static std::function<bool()> step;
+    return step;
+}
+
+// Orca's Tab::select_preset asks what to do with the outgoing preset's unsaved
+// edits ("Transfer or discard changes"). JusPrin never asks a person to save
+// or discard: the project is saved to its version history, which keeps the
+// edits, and they are dropped as Orca's Discard would. Without the shell's
+// save step, or when that save fails, they stay and Orca asks, so nothing is
+// lost. The caller holds a project-state transaction around this and the
+// selection, so the change log reads one switch, not a setting changed back.
+void drop_edits_kept_in_history(Tab& tab, const std::string& next_preset)
+{
+    PresetCollection& presets = *tab.get_presets();
+    if (presets.get_edited_preset().name == next_preset || !presets.current_is_dirty())
+        return;
+    if (!history_save_step() || !history_save_step()())
+        return;
+    presets.discard_current_changes();
+    tab.load_current_preset();
+}
+
 wxString option_string(const DynamicPrintConfig& config, const char* key, unsigned index = 0)
 {
     if (const auto* option = config.option<ConfigOptionStrings>(key); option && option->values.size() > index)
@@ -360,6 +385,7 @@ bool select_filament_preset(Plater& plater, std::size_t slot, const std::string&
     Tab*          tab    = wxGetApp().get_tab(Preset::TYPE_FILAMENT);
     if (preset == nullptr || tab == nullptr)
         return false;
+    const ProjectStateTransaction change = plater.project_state_transaction();

     // The sequence the sidebar's filament combo runs, without its own repaint
     // and AMS badge. There is no single public Orca call for "select filament
@@ -388,8 +414,10 @@ bool select_filament_preset(Plater& plater, std::size_t slot, const std::string&
     // keeps its own, and only the slot lists repaint.
     if (presets->filament_presets.size() > 1)
         plater.sidebar().update_presets(Preset::TYPE_FILAMENT);
-    else
+    else {
+        drop_edits_kept_in_history(*tab, preset_name);
         tab->select_preset(preset_name);
+    }
     plater.on_config_change(presets->full_config());
     return true;
 }
@@ -443,6 +471,11 @@ std::optional<std::size_t> add_filament_slot(Plater& plater)
     return presets->filament_presets.size() - 1;
 }

+void set_history_save_step(std::function<bool()> save)
+{
+    history_save_step() = std::move(save);
+}
+
 bool select_printer_preset(Plater& plater, const std::string& preset_name)
 {
     PresetBundle* presets = wxGetApp().preset_bundle;
@@ -454,6 +487,8 @@ bool select_printer_preset(Plater& plater, const std::string& preset_name)
     if (presets->printers.get_edited_preset().name == preset_name)
         return true;

+    const ProjectStateTransaction change = plater.project_state_transaction();
+    drop_edits_kept_in_history(*tab, preset_name);
     // The printer branch of Plater::priv::on_select_preset. The wrapper is
     // Orca's, and it is what keeps objects on their plates when the bed shape
     // changes with the preset.
@@ -470,6 +505,8 @@ bool select_process_preset(Plater& plater, const std::string& preset_name)
     Tab*          tab     = wxGetApp().get_tab(Preset::TYPE_PRINT);
     if (presets == nullptr || tab == nullptr || presets->prints.find_preset(preset_name) == nullptr)
         return false;
+    const ProjectStateTransaction change = plater.project_state_transaction();
+    drop_edits_kept_in_history(*tab, preset_name);
     tab->select_preset(preset_name);
     plater.on_config_change(presets->full_config());
     return true;
