+++ b/src/slic3r/GUI/JusPrin/Shell/ShellController.cpp
+#include "slic3r/GUI/NotificationManager.hpp"
+        // PROTOTYPE: OrcaSlicer's messages are taken while this view is on screen.
+        Workspace::set_view_takes_messages(true, [this] { return m_autosave && m_autosave->save_now(); });
+        // A plain message with no cause is about the project on screen: it
+        // goes where OrcaSlicer's own notices of an action's outcome already
+        // go, the confirmation on the canvas (PrintIssues/NoticeKinds).
+        Workspace::set_taken_message_listener([plater](const Workspace::TakenMessage& message) {
+            using From = Workspace::TakenMessage::From;
+            if (message.cause.kind == Workspace::Cause::Kind::None && (message.from == From::Box || message.from == From::ErrorBox || message.from == From::AppDialog))
+                plater->get_notification_manager()->push_notification(NotificationType::CustomNotification,
+                                                                      NotificationManager::NotificationLevel::RegularNotificationLevel, message.text);
+        });
+        tabpanel.Bind(wxEVT_BOOKCTRL_PAGE_CHANGING, &ShellController::on_notebook_page_changing, this);
+        Workspace::set_view_takes_messages(false);
+        Workspace::set_taken_message_listener({});
+    m_tabpanel->Unbind(wxEVT_BOOKCTRL_PAGE_CHANGING, &ShellController::on_notebook_page_changing, this);
+    Workspace::set_view_takes_messages(false);
+    Workspace::set_taken_message_listener({});
+// PROTOTYPE: the JusPrin view uses Home, Prepare and the project page. A
+// switch of the main window to any other OrcaSlicer page is refused, whatever
+// asked for it.
+void ShellController::on_notebook_page_changing(wxBookCtrlEvent& event)
+{
+    const wxString page = m_tabpanel != nullptr && event.GetSelection() >= 0 ? m_tabpanel->GetPageName(static_cast<size_t>(event.GetSelection())) : wxString();
+    if (m_installed && Workspace::view_takes_messages() && page != TAB_ID_HOME && page != TAB_ID_PREPARE && page != TAB_ID_PROJECT) {
+        Workspace::note_refused_page(std::string(page.ToUTF8().data()));
+        event.Veto();
+        return;
+    }
+    event.Skip();
+}
