#include "MessageRoutes.hpp"

#include "slic3r/GUI/DeviceManager.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/JusPrin/Printers/NamedPrinters.hpp"

#include <vector>

namespace Slic3r::GUI::JusPrin::OrcaMessages {

std::string printer_name(const std::string& device_id)
{
    for (const Printers::NamedPrinter& printer : Printers::named_printers())
        if (printer.device_id == device_id)
            return printer.name;
    if (DeviceManager* devices = wxGetApp().getDeviceManager())
        if (const MachineObject* machine = devices->get_my_machine(device_id); machine != nullptr && !machine->get_dev_name().empty())
            return machine->get_dev_name();
    return device_id;
}

void route(const TakenMessage& message, const Routes& routes)
{
    if (message.cause.told_elsewhere)
        return;
    using From = TakenMessage::From;
    if (message.from != From::Box && message.from != From::ErrorBox && message.from != From::AppDialog &&
        message.from != From::PrinterNotification)
        return;
    const bool about_a_printer = (message.cause.kind == Cause::Kind::PrinterConnection || message.cause.kind == Cause::Kind::PrinterMessage) &&
                                 !message.cause.printer.empty();
    if (about_a_printer) {
        // What the printer said is a failure the person reads after the fact:
        // the entry ends as it begins.
        const std::string id = routes.begin_entry(kPrinterEntryKind, printer_name(message.cause.printer));
        routes.finish_entry(id, "failed", message.text);
        return;
    }
    routes.confirm(message.text);
}

} // namespace Slic3r::GUI::JusPrin::OrcaMessages

#pragma once

// Where the JusPrin view shows a message it took from OrcaSlicer
// (OrcaMessages.hpp).
//
// - One about a printer (its answer to a connection, its reply to a command):
//   an entry in the project chat, the kind the app's own work leaves there
//   (Agent::AgentHost::begin_work), titled with the printer's name as JusPrin
//   names it and carrying OrcaSlicer's words. The chat panel opens for it.
// - One whose cause tells the person itself (Cause::told_elsewhere): nothing
//   more.
// - Any other message, from a box, an error box or GUI_App::show_dialog: the
//   confirmation on the canvas, where OrcaSlicer's own notices of an action's
//   outcome are drawn (PrintIssues/NoticeKinds.hpp).
// - The answered "Transfer or discard changes", a tip, a refused page switch:
//   nothing more.
//
// GUI thread only.

#include "OrcaMessages.hpp"

#include <functional>
#include <string>

namespace Slic3r::GUI::JusPrin::OrcaMessages {

struct Routes
{
    // The chat's entry for work outside it: begin returns its id, finish
    // ends it with a state (done, cancelled, failed) and a detail.
    std::function<std::string(const std::string& kind, const std::string& title)>                    begin_entry;
    std::function<void(const std::string& id, const std::string& state, const std::string& detail)> finish_entry;
    // A confirmation on the canvas.
    std::function<void(const std::string& text)> confirm;
};

// The kind of chat entry a printer's message makes.
inline constexpr const char* kPrinterEntryKind = "printer";

void route(const TakenMessage& message, const Routes& routes);

// The name the person knows the printer with this Bambu device id by: the
// named printer linked to it, else the name the printer gives itself, else
// the id.
std::string printer_name(const std::string& device_id);

} // namespace Slic3r::GUI::JusPrin::OrcaMessages

#pragma once

// What OrcaSlicer tells the person while the JusPrin view is on screen.
//
// OrcaSlicer speaks in one of two ways. It opens a modal box in the same call
// that decided to speak, or it puts the message off: GUI::show_error,
// GUI_App::show_dialog and GUI_App::push_notification queue the box and
// return. JusPrin takes the message at the last point where its reason is
// still known. For a box opened at once that is the modal hook every dialog
// passes (Workspace/DialogListeners.hpp), because the code that asked is still
// running. For a message put off it is one line at the top of each of the
// three functions, which hands the message here while its caller is still on
// the stack.
//
// The reason is a cause, noted at the doors where work comes in: a printer's
// answer to a connection (Printers::record_connection_event), a printer's
// reply (push_notification is given the printer), the network plug-in's
// message (GUI_App::process_network_msg), a slice that ended in an error and a
// failed upload (JusPrin's listeners of those events, which run before
// OrcaSlicer's own). A person's click in OrcaSlicer's own menus has no cause.
//
// The rule at the hook, for a window no listener answered:
// - A file or folder picker, a window with fields, and a question with a
//   choice are the person's, and open as OrcaSlicer's.
// - A message with only OK is taken, unless another window is open over the
//   main one: a box then belongs with that window, where the person is looking.
// - "Transfer or discard changes", and the unsaved-changes question OrcaSlicer
//   asks before it reloads presets, are answered after a version of the
//   project is saved: the setting changes are dropped and the version keeps
//   them. When no version can be saved, nothing changes and the failure is
//   reported as unexpected.
// - JusPrin's own windows (OwnDialogs.hpp) are never taken.
//
// What becomes of a taken message is the view's: see MessageRoutes.hpp.
//
// GUI thread only.

#include <wx/string.h>

#include <functional>
#include <optional>
#include <string>
#include <vector>

class wxDialog;
class wxWindow;

namespace Slic3r {
class MachineObject;
}

namespace Slic3r::GUI::JusPrin::OrcaMessages {

// What the app was handling when OrcaSlicer spoke. Noted by the code at the
// source, the only place that knows it.
struct Cause
{
    enum class Kind { None, PrinterConnection, PrinterMessage, PluginMessage, Slice, HostUpload };
    Kind        kind{Kind::None};
    std::string printer; // a Bambu device id, or a print host's address
    std::string detail;  // the plug-in's message code, the connection's answer
    // The code that noted the cause tells the person itself: the print issues
    // tell a failed slice, an upload's own entry its failure, the printer chat
    // the answer to the connection it is waiting for. Not shown again.
    bool        told_elsewhere{false};
};
const char* cause_name(Cause::Kind kind);

// The cause of what is said while this lives.
class ScopedCause
{
public:
    ScopedCause(Cause::Kind kind, std::string printer, std::string detail);
    ~ScopedCause();
    ScopedCause(const ScopedCause&)            = delete;
    ScopedCause& operator=(const ScopedCause&) = delete;

private:
    Cause        m_cause;
    ScopedCause* m_outer{nullptr};
    friend Cause current_cause();
};

// The cause until the event now being handled has ended: for a listener that
// returns before OrcaSlicer's own handler of the same event runs.
void  note_cause(Cause cause);
Cause current_cause();

// One thing OrcaSlicer wanted to tell the person, taken before its window
// opened, with the reason it was said.
struct TakenMessage
{
    enum class From { Box, ErrorBox, AppDialog, PrinterNotification, UnsavedChanges, Tip, PageSwitch };
    From        from{From::Box};
    Cause       cause;
    std::string title;
    std::string text;
};
const char* from_name(TakenMessage::From from);

// A window that reached the person while the view takes messages, and why.
struct ShownWindow
{
    std::string window_class;
    std::string title;
    std::string why;
};

// What the view gives while it is installed.
struct View
{
    // Saves the project to its version history; false when it could not, with
    // the reason in `error`.
    std::function<bool(std::string& error)> save_version;
    // Told of each message as it is taken.
    std::function<void(const TakenMessage&)> show;
};
void install(View view);
void uninstall();
// Installed, and taking messages.
bool taking();
// Tests only: turns the taking off and on while the view stays installed, so
// OrcaSlicer's own windows open as they do in the classic view.
void set_taking_for_tests(bool on);

// -- The hand-over points, called from OrcaSlicer's files through
//    OrcaHooks.hpp. Each returns true when the message was taken, and
//    OrcaSlicer's window must not open. ------------------------------------

// GUI_App::process_network_msg: what a box opened below it is about.
[[nodiscard]] ScopedCause plugin_message_cause(const std::string& device_id, const std::string& code);
// GUI_App::show_dialog.
bool take_app_message(const wxString& text);
// GUI_App::push_notification, with the printer it was given.
bool take_printer_message(const MachineObject* printer, const wxString& text, const wxString& title);
// GUI::show_error, through report_error_box (Workspace/FileLoads.hpp).
bool take_error(const std::string& text, wxWindow* parent);

// The modal hook's rule for a window no listener answered: the id ShowModal
// returns instead of showing it, or nothing to show it.
std::optional<int> take_modal(wxDialog& dialog);

// A switch of the main window to OrcaSlicer's page `page` was refused.
void note_refused_page(const std::string& page);

// Everything taken and let through in this run, for tests.
const std::vector<TakenMessage>& taken_messages();
const std::vector<ShownWindow>&  shown_windows();

// What the rule makes of a window, for a test that checks nothing it should
// take reached the person.
enum class WindowKind { Own, Picker, Chooser, UnsavedChanges, CopyQuestion, Tip, Window, Question, Message, MessageOverWindow };
WindowKind window_kind(wxDialog& dialog);
const char* window_kind_name(WindowKind kind);

} // namespace Slic3r::GUI::JusPrin::OrcaMessages

#include "OwnDialogs.hpp"

#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/MsgDialog.hpp"

#include <wx/dialog.h>
#include <wx/thread.h>
#include <wx/weakref.h>
#include <wx/window.h>

#include <algorithm>
#include <vector>

namespace Slic3r::GUI::JusPrin::OrcaMessages {

namespace {

// The own windows being shown, innermost last. Never destroyed: a window may
// be shown while statics are torn down at exit.
std::vector<const wxDialog*>& own_dialogs()
{
    static auto* const list = new std::vector<const wxDialog*>;
    return *list;
}

} // namespace

int show_own_modal(wxDialog& dialog)
{
    wxASSERT(wxIsMainThread());
    auto& list = own_dialogs();
    list.push_back(&dialog);
    struct Unmark
    {
        const wxDialog* dialog;
        ~Unmark()
        {
            auto& list = own_dialogs();
            list.erase(std::remove(list.begin(), list.end(), dialog), list.end());
        }
    } unmark{&dialog};
    return dialog.ShowModal();
}

int show_own_message(wxWindow* parent, const wxString& text, const wxString& title, long style)
{
    MessageDialog dialog(parent, text, title, style);
    return show_own_modal(dialog);
}

void show_own_error(wxWindow* parent, const wxString& text)
{
    wxGetApp().CallAfter([parent = wxWeakRef<wxWindow>(parent), text] {
        ErrorDialog dialog(parent.get(), text, false);
        show_own_modal(dialog);
    });
}

bool is_own_dialog(const wxDialog& dialog)
{
    const auto& list = own_dialogs();
    return std::find(list.begin(), list.end(), &dialog) != list.end();
}

} // namespace Slic3r::GUI::JusPrin::OrcaMessages

