            const std::string current = bundle.printers.get_edited_preset().name;
            for (const Preset& preset : bundle.printers)
                if (preset.is_visible && !preset.is_default && preset.name != current) {
                    self->m_om_other_printer = preset.name;
                    break;
                }
            self->check(!self->m_om_other_printer.empty() && self->om_printer_dirty(), "om_switch_has_an_edit_and_another_printer");
            self->om_mark();
            SetupCommands::select_printer_preset(*self->m_plater, self->m_om_other_printer);
        }, self->om_quiet_and(), [self] {
            bool                           opened   = false;
            const Workspace::TakenMessage* match    = self->om_report("switch_printer", "Transfer or discard", opened);
            const bool                     switched = wxGetApp().preset_bundle->printers.get_edited_preset().name == self->m_om_other_printer;
            std::cerr << "HARNESS MESSAGE NOTE switched=" << switched << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "switch_printer_today_orca_asks");
                return;
            }
            self->check(!opened, "switch_printer_asks_nothing");
            self->check(match != nullptr, "switch_printer_version_saved_and_edits_dropped");
            self->check(switched && !self->om_printer_dirty(), "switch_printer_switched");
        }});

