//              run; other programs on UDP 2021 hide the printer (see Testing/README.md)
//              A scenario plays the connection skill's chat against a printer in
//              LAN mode instead: lan stops at the access code form; wrong-code
//              types a made-up code twice; cloud-on
//              starts in cloud mode and waits, up to 15 minutes, for someone to
//              turn LAN Only on; real-code waits as long for someone to type the
//              real code into the form, or takes it from JUSPRIN_P1S_CODE, and
//              never prints it.
//   --printer-live-host <script>
//              needs ANTHROPIC_API_KEY or OPENAI_API_KEY: plays a person
//              connecting a print host through the live model, from a script
//              (see queue_printer_live_host). Prints every message, tool call
//              and note with its timing. Costs one live chat each run.
//   --print-host-check <cases-file> [<catalogue id>]
//              no model: a printer chat's connection tool called once per
//              line of "<moonraker|octoprint> <address> [<variable holding the
//              key> | MISSING | CANCEL]", printing what the model reads back.
//              When the host asks for a key the call waits on the form, which
    // OrcaSlicer message with only OK reached the person over the main
    // window, no unsaved-changes question reached them, and every printer
    // message the view took carried the printer it is about
    // (OrcaMessages.hpp).
    void check_no_orca_message_missed()
    {
        using OrcaMessages::TakenMessage;
        using OrcaMessages::WindowKind;
        for (const OrcaMessages::ShownWindow& window : OrcaMessages::shown_windows())
            if (window.kind == WindowKind::Message || window.kind == WindowKind::UnsavedChanges) {
                std::cerr << "HARNESS MISSED window '" << window.title << "' kind=" << OrcaMessages::window_kind_name(window.kind)
                          << " why='" << window.why << "'\n";
                check(false, "no_orca_message_reaches_the_person_in_the_jusprin_view");
            }
        for (const TakenMessage& message : OrcaMessages::taken_messages()) {
            const bool no_cause   = message.from == TakenMessage::From::AppDialog && message.cause.kind == OrcaMessages::Cause::Kind::None;
            const bool no_printer = message.from == TakenMessage::From::PrinterNotification && message.cause.printer.empty();
            if (no_cause || no_printer) {
                std::cerr << "HARNESS MISSED cause from=" << OrcaMessages::from_name(message.from) << " text='" << message.text << "'\n";
                check(false, "every_printer_message_taken_has_its_printer");
            }
        }
    }

