            self->m_om_before_brim    = bundle.prints.get_edited_preset().config.opt_serialize("brim_width");
            self->m_om_before_objects = self->m_plater->model().objects.size();
            std::cerr << "HARNESS MESSAGE NOTE before_switch printer='" << current << "' height=" << self->m_om_before_height
                      << " process='" << self->m_om_before_process << "' brim=" << self->m_om_before_brim
                      << " process_dirty=" << bundle.prints.current_is_dirty() << " objects=" << self->m_om_before_objects
                      << " versions=" << self->m_om_versions_before.size() << '\n';
            self->om_mark();
            SetupCommands::select_printer_preset(*self->m_plater, self->m_om_other_printer);
            // The version that is current as the switch returns: the one the
            // switch saved, or the one already holding the same project.
            self->m_om_version_at_switch = installed_shell()->autosave()->current_version();
            std::cerr << "HARNESS MESSAGE NOTE version_at_switch=" << self->m_om_version_at_switch
                      << " was_known=" << self->m_om_versions_before.count(self->m_om_version_at_switch) << '\n';
        }, self->om_quiet_and(), [self] {
            bool                           opened   = false;
            const Workspace::TakenMessage* match    = self->om_report("switch_printer", "Transfer or discard", opened);
            const bool                     switched = wxGetApp().preset_bundle->printers.get_edited_preset().name == self->m_om_other_printer;
            std::cerr << "HARNESS MESSAGE NOTE switched=" << switched << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "switch_printer_today_orca_asks");
                return;
            }
            self->check(!opened, "switch_printer_asks_nothing");
            self->check(match != nullptr, "switch_printer_version_saved_and_edits_dropped");
            self->check(switched && !self->om_printer_dirty(), "switch_printer_switched");
        }});

        // -- The version saved by that switch brings back the project as it
        //    was just before it: the printer, both unsaved setting changes
        //    and the objects. -----------------------------------------------
        steps.push_back({"om_restore_after_switch", [self] {
            if (!Workspace::view_takes_messages())
                return;
            PresetBundle& bundle = *wxGetApp().preset_bundle;
            std::cerr << "HARNESS MESSAGE NOTE after_switch printer='" << bundle.printers.get_edited_preset().name
                      << "' height=" << bundle.printers.get_edited_preset().config.opt_serialize("printable_height")
                      << " process='" << bundle.prints.get_edited_preset().name
                      << "' brim=" << bundle.prints.get_edited_preset().config.opt_serialize("brim_width")
                      << " process_dirty=" << bundle.prints.current_is_dirty() << '\n';
            auto* autosave = installed_shell()->autosave();
            std::cerr << "HARNESS MESSAGE NOTE current_version_now=" << autosave->current_version() << '\n';
            self->check(!self->m_om_version_at_switch.empty(), "switch_printer_left_a_version");
            if (self->m_om_version_at_switch.empty())
                return;
            self->om_mark();
            self->check(autosave->restore(self->m_om_version_at_switch), "switch_printer_version_restores");
        }, self->om_quiet_and(), [self] {
            if (!Workspace::view_takes_messages())
                return;
            PresetBundle&     bundle  = *wxGetApp().preset_bundle;
            const std::string printer = bundle.printers.get_edited_preset().name;
            const std::string height  = bundle.printers.get_edited_preset().config.opt_serialize("printable_height");
            const std::string process = bundle.prints.get_edited_preset().name;
            const std::string brim    = bundle.prints.get_edited_preset().config.opt_serialize("brim_width");
            std::cerr << "HARNESS MESSAGE NOTE restored printer='" << printer << "' height=" << height << " printer_dirty="
                      << self->om_printer_dirty() << " process='" << process << "' brim=" << brim
                      << " process_dirty=" << bundle.prints.current_is_dirty() << " objects=" << self->m_plater->model().objects.size() << '\n';
            self->check(printer == self->m_om_before_printer, "restore_brings_back_the_printer");
            self->check(height == self->m_om_before_height && height == "171", "restore_brings_back_the_printer_setting_change");
            self->check(process == self->m_om_before_process, "restore_brings_back_the_process_profile");
            self->check(brim == self->m_om_before_brim && brim == "9", "restore_brings_back_the_process_setting_change");
            self->check(self->m_plater->model().objects.size() == self->m_om_before_objects, "restore_brings_back_the_objects");
        }});

        // -- The same question on the path the import window and the setup
        //    wizard use, which reads the dialog's recorded choice. ----------
        steps.push_back({"om_edit_before_reload", [self] { self->om_edit_printer_setting("172"); }, {}, {}});
        steps.push_back({"om_unsaved_before_reload", [self] {
            self->check(self->om_printer_dirty(), "om_reload_has_an_edit");
            self->om_mark();
            self->m_om_went = wxGetApp().check_and_save_current_preset_changes(_L("Import from OrcaSlicer"), _L("Importing these printers loads their profiles."), false);
        }, self->om_quiet_and(), [self] {
            bool                           opened = false;
            const Workspace::TakenMessage* match  = self->om_report("unsaved_before_reload", "unsaved changes", opened);
            std::cerr << "HARNESS MESSAGE NOTE went_on=" << self->m_om_went << " dirty=" << self->om_printer_dirty() << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(opened, "unsaved_before_reload_today_orca_asks");
                return;
            }
            self->check(!opened, "unsaved_before_reload_asks_nothing");
            self->check(match != nullptr && self->m_om_went && !self->om_printer_dirty(), "unsaved_before_reload_goes_on_with_edits_dropped");
        }});

        // -- Code switches the main window to a page the JusPrin view hides,
        //    with the call MainFrame::jump_to_monitor and the "Go to" keys
        //    make. The Calibration page stands in for the Device page, which
        //    is not in the page list without the Bambu plug-in. -------------
        steps.push_back({"om_page_switch", [self] {
            self->om_mark();
            wxGetApp().mainframe->m_tabpanel->SelectPageByName(TAB_ID_CALIBRATION);
        }, self->om_quiet_and(), [self] {
            bool              opened = false;
            const auto*       match  = self->om_report("page_switch", TAB_ID_CALIBRATION, opened);
            const std::string page   = wxGetApp().mainframe->m_tabpanel->GetSelectedPageName().ToUTF8().data();
            std::cerr << "HARNESS MESSAGE NOTE page_now=" << page << '\n';
            if (!Workspace::view_takes_messages()) {
                self->check(page == TAB_ID_CALIBRATION, "page_switch_today_shows_a_hidden_orca_page");
                wxGetApp().mainframe->select_tab(wxString(TAB_ID_PREPARE));
                return;
            }
            self->check(page == TAB_ID_PREPARE && match != nullptr, "page_switch_is_refused");
