        g_dialog_witness->start();
        std::cerr << "HARNESS MESSAGE TAKING " << (om_taking() ? "on" : "off") << '\n';
        connect_fixture_to_fake_printer([self = shared_from_this()] { self->run_orca_messages(); });
    }

